/// Focus-star suffix drawn immediately after a starred session's title. Kept to
/// two display columns (space + glyph) so it costs the title field almost
/// nothing at narrow sidebar widths.
pub(crate) const SIDEBAR_STAR_SUFFIX: &str = " \u{2605}";
/// Below this the title field is too short to give up columns to the star, so a
/// starred row simply renders without it rather than truncating the name.
const SIDEBAR_STAR_MIN_TITLE_WIDTH: usize = 6;

pub(crate) fn sidebar_separator_col(area: Rect) -> Option<u16> {
    (area.width > 0).then(|| area.x + area.width.saturating_sub(1))
}

#[cfg(test)]
pub(super) fn title_repeats_agent_identity(entry: &AgentPanelEntry, title: &str) -> bool {
    let title = title.trim().to_ascii_lowercase();
    let provider = match entry.agent {
        Some(Agent::Codex) => Some("codex"),
        Some(Agent::Claude) => Some("claude"),
        Some(Agent::Pi) => Some("pi"),
        Some(Agent::Kimi) => Some("kimi"),
        _ => None,
    };
    entry
        .agent_label
        .as_deref()
        .into_iter()
        .chain(entry.agent_kind_label.as_deref())
        .chain(provider)
        .chain(crate::ui::icons::agent_text_tag(entry.agent))
        .any(|identity| identity.trim().eq_ignore_ascii_case(&title))
}

#[cfg(test)]
pub(super) fn canonical_sidebar_agent_identity(entry: &AgentPanelEntry) -> Option<&str> {
    crate::ui::icons::agent_text_tag(entry.agent)
        .or(entry.agent_kind_label.as_deref())
        .or_else(|| {
            entry
                .agent
                .is_none()
                .then_some(entry.agent_label.as_deref())
                .flatten()
        })
}

#[cfg(test)]
pub(super) fn compact_agent_identity<'a>(
    entry: &'a AgentPanelEntry,
    title: &str,
) -> Option<&'a str> {
    if title_repeats_agent_identity(entry, title) {
        return None;
    }
    canonical_sidebar_agent_identity(entry)
}

#[cfg(test)]
pub(super) fn tab_lifecycle_visible(entry: &AgentPanelEntry) -> bool {
    entry.has_agent
        && (entry.open_blockers
            || entry.usage_limited
            || entry.stale
            || entry.state != AgentState::Idle
            || !entry.seen)
}

/// Runtime severity shared by dots and the sidebar filter.
///
/// `entry_is_blocked` narrows this for navigation and the inbox: a retained
/// gate does not block a working pane. Once work stops, that same gate makes
/// the pane blocked without requiring a new report.
pub(crate) fn entry_attention_tier(entry: &AgentPanelEntry) -> AttentionTier {
    #[cfg(test)]
    ENTRY_ATTENTION_TIER_VISITS.with(|visits| visits.set(visits.get() + 1));
    entry.attention_tier.unwrap_or_else(|| {
        crate::terminal::state::attention_tier(
            entry.state,
            entry.open_blockers,
            false,
            entry.usage_limited,
        )
    })
}

pub(crate) fn entry_attention_rank(entry: &AgentPanelEntry) -> u8 {
    if !entry_is_blocked(entry) {
        return if entry_attention_tier(entry) == AttentionTier::Attention {
            1
        } else {
            0
        };
    }
    match entry_attention_tier(entry) {
        AttentionTier::None => 0,
        AttentionTier::Attention => 1,
        AttentionTier::Blocked => 2,
    }
}

#[cfg(test)]
thread_local! {
    static ENTRY_ATTENTION_TIER_VISITS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn take_entry_attention_tier_visits() -> usize {
    ENTRY_ATTENTION_TIER_VISITS.with(|visits| visits.replace(0))
}

pub(crate) fn entry_is_blocked(entry: &AgentPanelEntry) -> bool {
    entry_attention_tier(entry) == AttentionTier::Blocked
        && (entry.state != AgentState::Working || entry.usage_limited)
}

pub(crate) fn entry_needs_human_attention(entry: &AgentPanelEntry) -> bool {
    entry_attention_tier(entry) == AttentionTier::Attention || entry_is_blocked(entry)
}

pub(crate) fn entry_has_red_dot(entry: &AgentPanelEntry) -> bool {
    entry_is_blocked(entry)
}

/// A working pane keeps its blue lifecycle label while a human gate is latched.
/// Once work stops, the gate becomes blocking and supplies the blocked label.
/// Usage limits still override every lifecycle label.
#[cfg(test)]
pub(super) fn gate_overrides_label(entry: &AgentPanelEntry) -> bool {
    entry.usage_limited
        || (entry.open_blockers
            && !entry.stale
            && entry.state != AgentState::Blocked
            && entry.state != AgentState::Working)
}

/// A usage limit outranks every other label: the pane is not working, and no
/// answer from the human releases it — only the reset window does.
#[cfg(test)]
pub(super) fn usage_limit_label() -> &'static str {
    "usage"
}

#[cfg(test)]
pub(super) fn gate_override_label(entry: &AgentPanelEntry) -> String {
    if entry.usage_limited {
        return entry
            .state_labels
            .get("usage")
            .cloned()
            .unwrap_or_else(|| usage_limit_label().to_string());
    }
    entry
        .state_labels
        .get("blocked")
        .cloned()
        .unwrap_or_else(|| "blocked".to_string())
}

#[cfg(test)]
pub(super) fn agent_panel_label_color(
    entry: &AgentPanelEntry,
    p: &Palette,
) -> ratatui::style::Color {
    if entry_is_blocked(entry) {
        return p.red;
    }
    if entry_attention_tier(entry) == AttentionTier::Attention {
        return p.peach;
    }
    if entry.waiting_on_agents {
        return p.yellow;
    }
    state_label_color(entry.state, entry.seen, p)
}

pub(super) struct TabRowLayout {
    pub dot: String,
    pub title: String,
    pub provider: String,
    pub activity_age: Option<String>,
    pub activity_instant: Option<std::time::Instant>,
}

const SIDEBAR_DOT_FIELD_WIDTH: usize = 3;
/// Requested prefix of a task row at depth 1 (`depth * 3 + 1`); the Needs-you
/// strip lines its dot up with these rows.
const NEEDS_YOU_REQUESTED_PREFIX_WIDTH: usize = 4;
const SIDEBAR_PROVIDER_GAP_WIDTH: usize = 1;
const SIDEBAR_AGE_FIELD_WIDTH: usize = 5;
const SIDEBAR_AGE_MIN_ROW_WIDTH: usize = 24;
const SIDEBAR_MACHINE_LABEL_WIDTH: usize = 3;
const SIDEBAR_MACHINE_FIELD_WIDTH: usize = SIDEBAR_MACHINE_LABEL_WIDTH + 1;
const SIDEBAR_MIN_NESTED_TITLE_WIDTH: usize = 8;
const SIDEBAR_MIN_NESTED_PREFIX_WIDTH: usize = 3;
const SIDEBAR_TITLE_TARGET_WIDTH: usize = 16;
const SIDEBAR_SNOOZE_CONTROL_WIDTH: usize = 3;
const SIDEBAR_SETTLE_CONTROL_WIDTH: usize = 2;
const SIDEBAR_SELECTED_CONTROLS_WIDTH: usize =
    SIDEBAR_SNOOZE_CONTROL_WIDTH + SIDEBAR_SETTLE_CONTROL_WIDTH;
const SIDEBAR_SELECTED_MIN_TITLE_WIDTH: usize = 4;
const SIDEBAR_MIN_CONTROLS_ROW_WIDTH: u16 = 19;

fn entry_has_gate(entry: &AgentPanelEntry) -> bool {
    entry.gate_count > 0 || entry.open_blockers
}

fn compact_row_dot(entry: &AgentPanelEntry) -> &'static str {
    if entry.working_shelf {
        return " ";
    }
    // Waiting on subagents never hides a pane that owes the human something.
    if entry.waiting_on_agents && entry_attention_tier(entry) == AttentionTier::None {
        return "◌";
    }
    compact_dot_for_state(
        entry.state,
        entry.seen,
        entry.has_agent,
        entry.state == AgentState::Working && entry_has_gate(entry),
        entry.usage_limited,
    )
}

fn compact_row_dot_text(entry: &AgentPanelEntry) -> String {
    // Red already says the row owes you an answer; how many gates are open does
    // not change what you do next, so the count is not rendered.
    compact_row_dot(entry).to_string()
}

pub(crate) fn compact_dot_for_state(
    state: AgentState,
    // Seen no longer selects a shape: done-unread and idle-seen are both `○`,
    // separated by colour via state_label_color.
    _seen: bool,
    has_agent: bool,
    _gate: bool,
    _usage_limited: bool,
) -> &'static str {
    if !has_agent {
        return "·";
    }
    match state {
        AgentState::Working => "●",
        AgentState::Blocked => "○",
        AgentState::Idle if has_agent => "○",
        // Unknown agent state: a solid grey dot, not an empty one.
        _ => "●",
    }
}

/// AS1: the model letter. Shown only for (Claude, Fable) and (Codex, Astra);
/// every other pair, and an unknown model, shows nothing.
fn model_letter_for(
    agent: Option<crate::detect::Agent>,
    model: Option<&str>,
) -> Option<&'static str> {
    let model = model?.to_ascii_lowercase();
    match agent? {
        crate::detect::Agent::Claude if model.contains("fable") => Some(MODEL_LETTER_FABLE),
        crate::detect::Agent::Codex if model.contains("astra") => Some(MODEL_LETTER_ASTRA),
        _ => None,
    }
}

const MODEL_LETTER_FABLE: &str = "\u{A730}";
const MODEL_LETTER_ASTRA: &str = "\u{1D00}";

/// The model letter this row draws, which needs the Nerd Font agent icon.
fn row_model_letter(entry: &AgentPanelEntry, nerd_font: bool) -> Option<&'static str> {
    entry.model_letter.filter(|_| nerd_font)
}

fn compact_provider(entry: &AgentPanelEntry, nerd_font: bool) -> String {
    compact_provider_with(entry, nerd_font, row_model_letter(entry, nerd_font))
}

fn compact_provider_with(
    entry: &AgentPanelEntry,
    nerd_font: bool,
    model_letter: Option<&str>,
) -> String {
    compact_provider_token(entry, nerd_font, model_letter)
}

fn compact_provider_token(
    entry: &AgentPanelEntry,
    nerd_font: bool,
    model_letter: Option<&str>,
) -> String {
    if !entry.has_agent {
        return String::new();
    }
    let Some(agent) = entry.agent.or(entry.agent_context) else {
        return String::new();
    };
    let Some(suffix) = crate::ui::icons::agent_label(agent, nerd_font) else {
        return String::new();
    };
    let mut provider = suffix.to_string();
    if let Some(letter) = model_letter {
        provider.push_str(letter);
    }
    // Sub-agent counts are omitted from sidebar rows.
    provider
}

fn sidebar_machine_host<'a>(app: &'a AppState, entry: &'a AgentPanelEntry) -> &'a str {
    entry
        .remote_host
        .as_deref()
        .unwrap_or(app.agent_host_name.as_str())
}

/// Machine column label: the host's first three characters, lowercased and
/// padded, so `ub1`, `ub2`, `mbpro` and `mbair` read as `ub1`, `ub2`, `mbp`, `mba`.
fn sidebar_machine_icon(_app: &AppState, host: &str) -> String {
    let label: String = host
        .to_lowercase()
        .chars()
        .take(SIDEBAR_MACHINE_LABEL_WIDTH)
        .collect();
    format!("{label:<width$}", width = SIDEBAR_MACHINE_LABEL_WIDTH)
}

fn machine_icon_cell_offset(row_width: usize, age_width: usize) -> usize {
    row_width.saturating_sub(age_width + SIDEBAR_MACHINE_LABEL_WIDTH)
}

fn compact_age(
    entry: &AgentPanelEntry,
    now: std::time::Instant,
) -> (String, Option<std::time::Instant>) {
    let instant = entry
        .last_turn_at
        .map(|timestamp| timestamp.instant)
        .or(entry.reported_at)
        .or(entry.activity_at);
    let age = instant
        .and_then(|instant| status_report_age_compact_label(Some(instant), now))
        .unwrap_or_else(|| "—".to_string());
    (age, instant)
}

fn reply_timestamp(value: Option<&str>, now: std::time::Instant) -> Option<AgentReplyTimestamp> {
    let unix_seconds = crate::fleet::parse_utc_timestamp(value?)?;
    let now_unix_seconds = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()?
        .as_secs();
    let age = now_unix_seconds.checked_sub(unix_seconds)?;
    Some(AgentReplyTimestamp {
        instant: now.checked_sub(std::time::Duration::from_secs(age))?,
        unix_seconds,
    })
}

fn cached_reply_timestamp(
    instant: Option<std::time::Instant>,
    unix_seconds: Option<u64>,
) -> Option<AgentReplyTimestamp> {
    Some(AgentReplyTimestamp {
        instant: instant?,
        unix_seconds: unix_seconds?,
    })
}

fn age_words(instant: std::time::Instant, now: std::time::Instant) -> String {
    let minutes = now
        .checked_duration_since(instant)
        .unwrap_or_default()
        .as_secs()
        / 60;
    if minutes >= 60 {
        format!("{}h {}m", minutes / 60, minutes % 60)
    } else {
        format!("{minutes}m")
    }
}

fn age_tooltip(
    last_turn_at: Option<AgentReplyTimestamp>,
    reported_at: Option<std::time::Instant>,
    now: std::time::Instant,
) -> String {
    if let Some(last_turn_at) = last_turn_at {
        let ago = age_words(last_turn_at.instant, now);
        let clock = crate::platform::local_datetime_at(last_turn_at.unix_seconds)
            .map(|local| format!("{:02}:{:02}", local.hour(), local.minute()))
            .unwrap_or_else(|| "local time unavailable".to_string());
        format!("Last reply {ago} ago\n({clock})")
    } else {
        let ago = reported_at
            .map(|instant| format!("{} ago", age_words(instant, now)))
            .unwrap_or_else(|| "time unavailable".to_string());
        format!("Last status report {ago}\nAgent reply time unavailable")
    }
}

fn remote_compact_age(remote: &RemoteAgentPanelEntry, now: std::time::Instant) -> String {
    remote
        .snoozed_until
        .and_then(crate::platform::local_datetime_at)
        .map(|deadline| format!("{:02}:{:02}", deadline.hour(), deadline.minute()))
        .unwrap_or_else(|| compact_age(&remote.entry, now).0)
}

fn compact_row_title(entry: &AgentPanelEntry, tab: bool) -> &str {
    let candidate = if tab {
        entry.primary_tab_label.as_deref()
    } else if entry.pane_label_is_agent_identity {
        entry
            .primary_tab_label
            .as_deref()
            .or(entry.terminal_title_stripped.as_deref())
    } else {
        entry
            .pane_label
            .as_deref()
            .or(entry.terminal_title_stripped.as_deref())
    };
    let candidate = if (entry.tab_label_leads_with_agent && !entry.tab_has_custom_name) || !tab {
        compact_title_candidate(candidate)
    } else {
        candidate.map(str::trim).filter(|title| {
            !title.is_empty()
                && !title.eq_ignore_ascii_case(DEFAULT_THREAD_TITLE)
                && !title.eq_ignore_ascii_case("Terminal")
        })
    };
    candidate.unwrap_or(DEFAULT_THREAD_TITLE)
}

pub(crate) fn title_without_object_identifier(title: &str) -> Option<&str> {
    let (identifier, title) = title.split_once(" · ")?;
    let github_identifier = identifier
        .strip_prefix('#')
        .is_some_and(|number| !number.is_empty() && number.chars().all(|c| c.is_ascii_digit()));
    let linear_identifier = identifier.split_once('-').is_some_and(|(team, number)| {
        !team.is_empty()
            && team.chars().all(|c| c.is_ascii_alphabetic())
            && !number.is_empty()
            && number.chars().all(|c| c.is_ascii_digit())
    });
    (github_identifier || linear_identifier).then_some(title)
}

fn compact_row_title_for_width<'a>(
    title: &'a str,
    provider: &str,
    width: usize,
    requested_prefix: usize,
) -> &'a str {
    if width >= SIDEBAR_WIDE_ROW_MIN_WIDTH {
        return title;
    }
    let Some(title_only) = title_without_object_identifier(title) else {
        return title;
    };
    let widths = compact_row_widths(title, provider, width, requested_prefix);
    let fixed_width = requested_prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + widths.provider
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + widths.age;
    if display_width(title) <= width.saturating_sub(fixed_width) {
        title
    } else {
        title_only
    }
}

fn compact_title_candidate(title: Option<&str>) -> Option<&str> {
    let title = title?.trim();
    if title.is_empty()
        || title.eq_ignore_ascii_case(DEFAULT_THREAD_TITLE)
        || title.eq_ignore_ascii_case("Terminal")
        || (title.contains('.')
            && title
                .chars()
                .all(|character| character.is_ascii_digit() || character == '.'))
    {
        None
    } else {
        Some(title)
    }
}

fn compact_row_layout(
    entry: &AgentPanelEntry,
    now: std::time::Instant,
    width: usize,
    prefix_width: usize,
    tab: bool,
    nerd_font: bool,
) -> TabRowLayout {
    let (age, activity_instant) = compact_age(entry, now);
    let provider = compact_provider(entry, nerd_font);
    let title = compact_row_title_for_width(
        compact_row_title(entry, tab),
        &provider,
        width,
        prefix_width,
    );
    let widths = compact_row_widths(title, &provider, width, prefix_width);
    let fixed_width = widths.prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + widths.provider
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + widths.age;
    TabRowLayout {
        dot: compact_row_dot_text(entry),
        title: truncate_end(title, width.saturating_sub(fixed_width)),
        provider,
        activity_age: (widths.age > 0).then_some(age),
        activity_instant: (widths.age > 0).then_some(activity_instant).flatten(),
    }
}

/// The sidebar's own vocabulary for one agent row, for surfaces that list the
/// same agents elsewhere and must not drift from it.
#[derive(Clone)]
pub(crate) struct AgentRowCells {
    pub dot: String,
    pub dot_color: Color,
    pub title: String,
    pub provider: String,
    pub provider_color: Color,
}

pub(crate) fn agent_row_cells(
    entry: &AgentPanelEntry,
    p: &Palette,
    nerd_font: bool,
) -> AgentRowCells {
    AgentRowCells {
        dot: compact_row_dot_text(entry),
        dot_color: compact_row_color(entry, p),
        title: compact_row_title(entry, true).to_string(),
        provider: compact_provider_with(entry, nerd_font, None),
        provider_color: provider_color(entry, p),
    }
}

fn compact_provider_field_width(provider: &str) -> usize {
    if provider.is_empty() {
        0
    } else {
        display_width(provider) + SIDEBAR_PROVIDER_GAP_WIDTH
    }
}

struct CompactRowWidths {
    prefix: usize,
    provider: usize,
    age: usize,
}

/// The prefix a compact task row with this title and provider gets at `width`,
/// computed exactly as `render_compact_agent_row_with_prefix` does.
fn compact_row_prefix_width(
    title: &str,
    provider: &str,
    width: usize,
    requested_prefix: usize,
) -> usize {
    let title = compact_row_title_for_width(title, provider, width, requested_prefix);
    compact_row_widths(title, provider, width, requested_prefix).prefix
}

fn compact_row_widths(
    title: &str,
    provider: &str,
    width: usize,
    requested_prefix: usize,
) -> CompactRowWidths {
    compact_row_widths_with_machine(
        title,
        provider,
        width,
        requested_prefix,
        SIDEBAR_MACHINE_FIELD_WIDTH,
    )
}

fn compact_row_widths_with_machine(
    title: &str,
    provider: &str,
    width: usize,
    requested_prefix: usize,
    machine_width: usize,
) -> CompactRowWidths {
    let provider = compact_provider_field_width(provider);
    let title_width = display_width(title);
    let readable_title_width = title_width.min(SIDEBAR_MIN_NESTED_TITLE_WIDTH);
    let minimum_prefix_width = requested_prefix.min(SIDEBAR_MIN_NESTED_PREFIX_WIDTH);
    let age = if width >= SIDEBAR_AGE_MIN_ROW_WIDTH
        && width
            >= SIDEBAR_DOT_FIELD_WIDTH
                + provider
                + machine_width
                + SIDEBAR_AGE_FIELD_WIDTH
                + readable_title_width
                + minimum_prefix_width
    {
        SIDEBAR_AGE_FIELD_WIDTH
    } else {
        0
    };
    let target_title_width = title_width.min(SIDEBAR_TITLE_TARGET_WIDTH);
    let prefix_budget = width
        .saturating_sub(SIDEBAR_DOT_FIELD_WIDTH + provider + machine_width + age)
        .saturating_sub(target_title_width);
    let preserve_nested_prefix = requested_prefix > 0
        && width
            >= SIDEBAR_DOT_FIELD_WIDTH
                + provider
                + machine_width
                + age
                + readable_title_width
                + minimum_prefix_width;
    let prefix = requested_prefix.min(if preserve_nested_prefix {
        prefix_budget.max(minimum_prefix_width)
    } else {
        prefix_budget
    });
    CompactRowWidths {
        prefix,
        provider,
        age,
    }
}

fn compact_row_color(entry: &AgentPanelEntry, p: &Palette) -> Color {
    if entry_is_blocked(entry) {
        return p.red;
    }
    if entry_attention_tier(entry) == AttentionTier::Attention {
        return p.peach;
    }
    // A session that declared a contract and reported it met is the one kind of
    // done you can act on without reading the pane: close it. That earns its own
    // colour rather than a fourth dot shape.
    if entry.completion_tier == Some(CompletionTier::ContractSatisfied) {
        return p.mauve;
    }
    if entry.waiting_on_agents {
        return p.yellow;
    }
    state_label_color(entry.state, entry.seen, p)
}

fn provider_color(entry: &AgentPanelEntry, p: &Palette) -> Color {
    match entry.agent.or(entry.agent_context) {
        Some(Agent::Claude) => crate::ui::icons::claude_color(p),
        Some(Agent::Codex) => crate::ui::icons::codex_color(p),
        Some(Agent::Pi) => p.mauve,
        Some(Agent::Kimi) => p.yellow,
        _ => p.overlay0,
    }
}

fn pad_right(text: &str, width: usize) -> String {
    format!(
        "{text}{}",
        " ".repeat(width.saturating_sub(display_width(text)))
    )
}

fn pad_left(text: &str, width: usize) -> String {
    format!(
        "{}{}",
        " ".repeat(width.saturating_sub(display_width(text))),
        text
    )
}

fn compact_row_style(style: Style, bg: Option<Color>) -> Style {
    bg.map_or(style, |bg| style.bg(bg))
}

/// Terminal cells have no alpha channel, so fade the foreground toward the
/// background actually painted under this row. Named and indexed colours use
/// their xterm RGB values; an inherited terminal background can only use DIM.
fn blue_working_state(
    state: AgentState,
    attention_tier: AttentionTier,
    p: &Palette,
    dot_color: Color,
) -> bool {
    state == AgentState::Working && attention_tier == AttentionTier::None && dot_color == p.blue
}

fn blue_working_row(entry: &AgentPanelEntry, p: &Palette, dot_color: Color) -> bool {
    blue_working_state(entry.state, entry_attention_tier(entry), p, dot_color)
}

fn opacity_style(app: &AppState, opacity: u8, style: Style, bg: Option<Color>) -> Style {
    if opacity == 100 {
        return compact_row_style(style, bg);
    }
    let row_bg = bg.unwrap_or_else(|| app.palette.sidebar_background());
    // Reset inherits colors that the TUI cannot query. Use the conventional
    // terminal defaults so every configured level still produces a distinct
    // cell instead of collapsing 75/50/25% into the same DIM modifier.
    let foreground = style.fg.and_then(crate::app::state::color_rgb).unwrap_or(
        crate::terminal_theme::RgbColor {
            r: 192,
            g: 192,
            b: 192,
        },
    );
    let background = crate::app::state::color_rgb(row_bg)
        .unwrap_or(crate::terminal_theme::RgbColor { r: 0, g: 0, b: 0 });
    let blend = |foreground: u8, background: u8| {
        ((u16::from(foreground) * u16::from(opacity)
            + u16::from(background) * u16::from(100 - opacity)
            + 50)
            / 100) as u8
    };
    let style = style.fg(Color::Rgb(
        blend(foreground.r, background.r),
        blend(foreground.g, background.g),
        blend(foreground.b, background.b),
    ));
    compact_row_style(style, bg)
}

fn working_row_style(app: &AppState, fade: bool, style: Style, bg: Option<Color>) -> Style {
    let opacity = if fade {
        app.working_row_opacity_percent
    } else {
        100
    };
    opacity_style(app, opacity, style, bg)
}

pub(super) fn section_row_style(
    app: &AppState,
    collapsed: bool,
    zero: bool,
    style: Style,
) -> Style {
    if !collapsed && !zero {
        return style;
    }
    let opacity = if zero {
        app.working_row_opacity_percent.saturating_div(2).max(12)
    } else {
        app.working_row_opacity_percent
    };
    opacity_style(app, opacity, style.add_modifier(Modifier::DIM), None)
}

fn superscript(index: usize) -> String {
    index
        .to_string()
        .chars()
        .map(|digit| match digit {
            '0' => '⁰',
            '1' => '¹',
            '2' => '²',
            '3' => '³',
            '4' => '⁴',
            '5' => '⁵',
            '6' => '⁶',
            '7' => '⁷',
            '8' => '⁸',
            '9' => '⁹',
            _ => digit,
        })
        .collect()
}

pub(super) fn sidebar_workspace_labels(
    app: &AppState,
    terminal_runtimes: &TerminalRuntimeRegistry,
) -> std::collections::HashMap<usize, (String, bool)> {
    let mut labels = std::collections::HashMap::new();
    for (ws_idx, ws) in app.workspaces.iter().enumerate() {
        let members = sidebar_space_member_indices(app, ws_idx);
        // Members of a worktree group share one checkout identity, so a name any
        // of them carries names the group. Repository groups collect Spaces that
        // only share a repo, and one member's rename must not retitle the row.
        let manual = if ws.worktree_space().is_some() {
            members
                .iter()
                .filter_map(|member| app.workspaces.get(*member))
                .find_map(|member| member.custom_name.clone())
        } else {
            ws.custom_name.clone()
        };
        let label = manual.map(|label| (label, false)).unwrap_or_else(|| {
            (
                ws.display_name_from(&app.terminals, terminal_runtimes),
                true,
            )
        });
        labels.insert(ws_idx, label);
    }
    let mut duplicate_positions = std::collections::HashMap::<String, usize>::new();
    let mut duplicate_counts = std::collections::HashMap::<String, usize>::new();
    for (label, _) in labels.values() {
        *duplicate_counts.entry(label.clone()).or_default() += 1;
    }
    for ws_idx in 0..app.workspaces.len() {
        let Some((label, _derived)) = labels.get_mut(&ws_idx) else {
            continue;
        };
        if duplicate_counts.get(label).copied().unwrap_or_default() > 1 {
            let position = duplicate_positions.entry(label.clone()).or_default();
            *position += 1;
            label.push_str(&superscript(*position));
        }
    }
    labels
}

