fn render_remote_compact_agent_row_with_prefix(
    app: &AppState,
    frame: &mut Frame,
    remote: &RemoteAgentPanelEntry,
    rect: Rect,
    depth: u16,
    bg: Option<Color>,
    prefix_override: Option<usize>,
    _show_host_identity: bool,
    working_shelf: bool,
) {
    if rect.width == 0 || rect.height == 0 {
        return;
    }
    if let Some(bg) = bg {
        frame.buffer_mut().set_style(rect, Style::default().bg(bg));
    }

    let p = &app.palette;
    let render_age = remote_compact_age(remote, app.view_observed_at);
    let requested_prefix = prefix_override.unwrap_or_else(|| usize::from(depth) * 3 + 1);
    let total_width = usize::from(rect.width);
    let row_width = total_width;
    let title = compact_row_title_for_width(
        &remote.render_title,
        &remote.render_provider,
        row_width,
        requested_prefix,
    );
    let widths = compact_row_widths(title, &remote.render_provider, row_width, requested_prefix);
    let provider_width = widths.provider;
    let age_width = widths.age;
    let fixed_width = widths.prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + provider_width
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + age_width;
    let title_width = row_width.saturating_sub(fixed_width);
    let selected = app
        .sidebar_selected_remote_agent
        .as_ref()
        .is_some_and(|selected| selected == &remote.agent_ref);
    let control = remote_row_control(remote);
    let show_controls = control.as_ref().is_some_and(|control| control.snoozed)
        || selected
        || app.view.layout == crate::app::state::ViewLayout::Mobile
        || sidebar_row_is_hovered(app, rect.y);
    let controls_width = selected_row_controls_width(
        show_controls.then_some(control.as_ref()).flatten(),
        title_width,
        rect.width,
    );
    let title_text_width = title_width.saturating_sub(controls_width);
    let title_text = truncate_end(title, title_text_width);
    let title_style = if selected {
        Style::default()
            .fg(active_sidebar_title_color(p))
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(p.subtext0)
    };
    let dot_color = compact_row_color(remote, p);
    let fade =
        remote.snoozed_until.is_some() || blue_working_row(remote, p, dot_color) || working_shelf;
    let row_style = |style| {
        let style = working_row_style(app, fade, style, bg);
        if working_shelf {
            style.add_modifier(Modifier::DIM)
        } else {
            style
        }
    };
    let dot_style = Style::default().fg(dot_color);
    let provider_style = Style::default()
        .fg(provider_color(remote, p))
        .add_modifier(Modifier::DIM);
    let age_style = Style::default().fg(if remote.snoozed_until.is_some() {
        p.overlay0
    } else {
        p.yellow
    });

    let mut x = rect.x.saturating_add(widths.prefix as u16);
    frame.render_widget(
        Paragraph::new(Span::styled(
            if working_shelf {
                " "
            } else {
                remote.render_dot
            },
            row_style(dot_style),
        )),
        Rect::new(x, rect.y, SIDEBAR_DOT_FIELD_WIDTH as u16, rect.height),
    );
    x = x.saturating_add(SIDEBAR_DOT_FIELD_WIDTH as u16);
    frame.render_widget(
        Paragraph::new(Span::styled(title_text, row_style(title_style))),
        Rect::new(x, rect.y, title_text_width as u16, rect.height),
    );
    x = x.saturating_add(title_text_width as u16);
    if controls_width > 0 {
        frame.render_widget(
            Paragraph::new(Span::styled(" ◷ ", row_style(Style::default().fg(p.mauve)))),
            Rect::new(x, rect.y, SIDEBAR_SNOOZE_CONTROL_WIDTH as u16, rect.height),
        );
        x = x.saturating_add(SIDEBAR_SNOOZE_CONTROL_WIDTH as u16);
        if control.as_ref().is_some_and(|control| control.show_settle) {
            frame.render_widget(
                Paragraph::new(Span::styled(
                    " ✓",
                    row_style(Style::default().fg(p.overlay0)),
                )),
                Rect::new(x, rect.y, SIDEBAR_SETTLE_CONTROL_WIDTH as u16, rect.height),
            );
            x = x.saturating_add(SIDEBAR_SETTLE_CONTROL_WIDTH as u16);
        }
    }
    if provider_width > 0 {
        frame.render_widget(
            Paragraph::new(Span::styled(
                remote.render_provider.as_str(),
                row_style(provider_style),
            ))
            .alignment(Alignment::Right),
            Rect::new(x, rect.y, provider_width as u16, rect.height),
        );
        x = x.saturating_add(provider_width as u16);
    }
    let machine_icon = sidebar_machine_icon(app, &remote.agent_ref.host);
    frame.render_widget(
        Paragraph::new(Span::styled(
            machine_icon,
            working_row_style(app, fade, Style::default().fg(p.overlay0), bg),
        ))
        .alignment(Alignment::Right),
        Rect::new(x, rect.y, SIDEBAR_MACHINE_FIELD_WIDTH as u16, rect.height),
    );
    x = x.saturating_add(SIDEBAR_MACHINE_FIELD_WIDTH as u16);
    if age_width > 0 {
        frame.render_widget(
            Paragraph::new(Span::styled(render_age.as_str(), row_style(age_style)))
                .alignment(Alignment::Right),
            Rect::new(x, rect.y, age_width as u16, rect.height),
        );
    }
    if rect.height > 1 {
        if let Some(ask) = visible_pending_ask(app, &remote.entry) {
            let subtitle = format!("{}↳ {ask}", " ".repeat(requested_prefix));
            frame.render_widget(
                Paragraph::new(Span::styled(
                    truncate_end(&subtitle, usize::from(rect.width)),
                    Style::default().fg(p.overlay0).add_modifier(Modifier::DIM),
                )),
                Rect::new(rect.x, rect.y.saturating_add(1), rect.width, 1),
            );
        }
    }
}

fn render_compact_agent_row_with_prefix(
    app: &AppState,
    frame: &mut Frame,
    entry: &AgentPanelEntry,
    rect: Rect,
    depth: u16,
    tab: bool,
    bg: Option<Color>,
    prefix_override: Option<usize>,
) {
    if rect.width == 0 || rect.height == 0 {
        return;
    }
    let Some(target) = entry.local_target() else {
        return;
    };
    let p = &app.palette;
    let requested_prefix_width = prefix_override.unwrap_or_else(|| usize::from(depth) * 3 + 1);
    let provider = compact_provider(entry, app.nerd_font);
    let row_title = compact_row_title_for_width(
        compact_row_title(entry, tab),
        &provider,
        usize::from(rect.width),
        requested_prefix_width,
    );
    let widths = compact_row_widths(
        row_title,
        &provider,
        usize::from(rect.width),
        requested_prefix_width,
    );
    let prefix = " ".repeat(widths.prefix);
    let layout = compact_row_layout(
        entry,
        app.view_observed_at,
        usize::from(rect.width),
        widths.prefix,
        tab,
        app.nerd_font,
    );
    let fixed_width = widths.prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + widths.provider
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + widths.age;
    let title_width = usize::from(rect.width).saturating_sub(fixed_width);
    let control_pane = row_control_pane(app, entry, tab);
    let show_controls = control_pane.as_ref().is_some_and(|control| control.snoozed)
        || selected_local_row_pane(app, entry, tab).is_some()
        || app.view.layout == crate::app::state::ViewLayout::Mobile
        || sidebar_row_is_hovered(app, rect.y);
    let controls_width = selected_row_controls_width(
        show_controls.then_some(control_pane.as_ref()).flatten(),
        title_width,
        rect.width,
    );
    let snoozed = control_pane.as_ref().is_some_and(|control| control.snoozed);
    // The star sits inside the title field, right after the name, so it reads as
    // part of the session's label rather than as another right-hand column.
    let star_suffix = (entry.starred
        && title_width >= SIDEBAR_STAR_MIN_TITLE_WIDTH + display_width(SIDEBAR_STAR_SUFFIX))
    .then_some(SIDEBAR_STAR_SUFFIX);
    let title_text_width = title_width
        .saturating_sub(star_suffix.map_or(0, display_width))
        .saturating_sub(controls_width);
    let title_text = truncate_end(&layout.title, title_text_width);
    let title_pad = " ".repeat(title_text_width.saturating_sub(display_width(&title_text)));
    let dot = pad_right(&layout.dot, SIDEBAR_DOT_FIELD_WIDTH);
    let provider = pad_left(&layout.provider, widths.provider);
    let machine_icon = sidebar_machine_icon(app, sidebar_machine_host(app, entry));
    let age = layout
        .activity_age
        .as_deref()
        .map_or_else(String::new, |age| pad_left(age, widths.age));
    let is_active = tab
        && app.active == Some(target.ws_idx)
        && app
            .workspaces
            .get(target.ws_idx)
            .is_some_and(|ws| ws.active_tab_index() == target.tab_idx);
    let title_style =
        if is_active || app.is_active_pane(target.ws_idx, target.tab_idx, target.pane_id) {
            Style::default()
                .fg(active_sidebar_title_color(p))
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(p.subtext0)
        };
    let dot_color = compact_row_color(entry, p);
    let fade = blue_working_row(entry, p, dot_color) || entry.working_shelf;
    let row_style = |style| {
        let style = working_row_style(app, fade, style, bg);
        if entry.working_shelf {
            style.add_modifier(Modifier::DIM)
        } else {
            style
        }
    };
    let dot_style = Style::default().fg(dot_color);
    let provider_style = Style::default()
        .fg(provider_color(entry, p))
        .add_modifier(Modifier::DIM);
    let age_style = Style::default().fg(p.yellow);
    let mut spans = vec![
        Span::styled(prefix, row_style(compact_row_style(Style::default(), bg))),
        Span::styled(dot, row_style(dot_style)),
        Span::styled(title_text, row_style(title_style)),
    ];
    if let Some(star) = star_suffix {
        spans.push(Span::styled(star, row_style(Style::default().fg(p.yellow))));
    }
    spans.extend([
        Span::styled(title_pad, row_style(title_style)),
        Span::styled(
            if controls_width > 0 { " ◷ " } else { "" },
            row_style(Style::default().fg(p.mauve)),
        ),
        Span::styled(
            if controls_width == SIDEBAR_SELECTED_CONTROLS_WIDTH && !snoozed {
                " ✓"
            } else {
                ""
            },
            row_style(Style::default().fg(p.overlay0)),
        ),
    ]);
    let provider_style = row_style(provider_style);
    match row_model_letter(entry, app.nerd_font).and_then(|letter| {
        provider.find(letter).map(|at| {
            (
                letter,
                provider[..at].to_string(),
                provider[at + letter.len()..].to_string(),
            )
        })
    }) {
        Some((letter, before, after)) => spans.extend([
            Span::styled(before, provider_style),
            Span::styled(letter, row_style(compact_row_style(Style::default(), bg))),
            Span::styled(after, provider_style),
        ]),
        None => spans.push(Span::styled(provider, provider_style)),
    }
    spans.extend([
        Span::styled(
            format!(" {machine_icon}"),
            row_style(Style::default().fg(p.overlay0)),
        ),
        Span::styled(age, row_style(age_style)),
    ]);
    frame.render_widget(Paragraph::new(Line::from(spans)), rect);
}

fn selected_local_row_pane(
    app: &AppState,
    entry: &AgentPanelEntry,
    tab: bool,
) -> Option<crate::layout::PaneId> {
    let target = entry.local_target()?;
    if tab
        && app.active == Some(target.ws_idx)
        && app
            .workspaces
            .get(target.ws_idx)
            .is_some_and(|workspace| workspace.active_tab_index() == target.tab_idx)
    {
        return Some(target.pane_id);
    }
    app.is_active_pane(target.ws_idx, target.tab_idx, target.pane_id)
        .then_some(target.pane_id)
}

fn sidebar_row_is_hovered(app: &AppState, row_y: u16) -> bool {
    match app.hovered_control {
        Some(crate::app::state::ControlId::SidebarRowHover(hovered_y)) => hovered_y == row_y,
        Some(crate::app::state::ControlId::SidebarHover(index)) => app
            .view
            .sidebar_hover_targets
            .get(index)
            .is_some_and(|target| target.rect.y == row_y),
        _ => false,
    }
}

#[derive(Clone)]
struct SidebarRowControl {
    target: crate::app::state::SidebarPaneLifecycleTarget,
    snoozed: bool,
    show_settle: bool,
}

fn row_control_pane(
    app: &AppState,
    entry: &AgentPanelEntry,
    tab: bool,
) -> Option<SidebarRowControl> {
    let target = entry.local_target()?;
    let pane_id = selected_local_row_pane(app, entry, tab).unwrap_or(target.pane_id);
    if !app.pane_can_snooze(target.ws_idx, pane_id) {
        return None;
    }
    let snoozed = app.pane_is_snoozed(target.ws_idx, pane_id);
    Some(SidebarRowControl {
        target: crate::app::state::SidebarPaneLifecycleTarget::Local(
            crate::app::state::PaneFocusTarget {
                workspace_id: app.workspaces.get(target.ws_idx)?.id.clone(),
                pane_id,
            },
        ),
        snoozed,
        show_settle: !snoozed,
    })
}

fn remote_row_control(entry: &RemoteAgentPanelEntry) -> Option<SidebarRowControl> {
    if !entry.host_fresh || entry.settled || entry_needs_human_attention(entry) {
        return None;
    }
    let snoozed = entry.snoozed_until.is_some();
    Some(SidebarRowControl {
        target: crate::app::state::SidebarPaneLifecycleTarget::Remote(entry.agent_ref.clone()),
        snoozed,
        show_settle: !snoozed,
    })
}

fn selected_row_controls_width(
    control_pane: Option<&SidebarRowControl>,
    title_width: usize,
    row_width: u16,
) -> usize {
    control_pane
        .filter(|_| row_width >= SIDEBAR_MIN_CONTROLS_ROW_WIDTH)
        .filter(|control| {
            let controls_width = SIDEBAR_SNOOZE_CONTROL_WIDTH
                + usize::from(control.show_settle) * SIDEBAR_SETTLE_CONTROL_WIDTH;
            title_width >= SIDEBAR_SELECTED_MIN_TITLE_WIDTH + controls_width
        })
        .map_or(0, |control| {
            SIDEBAR_SNOOZE_CONTROL_WIDTH
                + usize::from(control.show_settle) * SIDEBAR_SETTLE_CONTROL_WIDTH
        })
}

pub(crate) fn selected_row_control_at(
    app: &AppState,
    entry: &AgentPanelEntry,
    rect: Rect,
    depth: u16,
    tab: bool,
    column: u16,
) -> Option<crate::app::state::SidebarHoverAction> {
    let requested_prefix = usize::from(depth) * 3 + 1;
    let provider = compact_provider(entry, app.nerd_font);
    let title = compact_row_title_for_width(
        compact_row_title(entry, tab),
        &provider,
        usize::from(rect.width),
        requested_prefix,
    );
    let widths = compact_row_widths(title, &provider, usize::from(rect.width), requested_prefix);
    let fixed_width = widths.prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + widths.provider
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + widths.age;
    let title_width = usize::from(rect.width).saturating_sub(fixed_width);
    let selected = selected_local_row_pane(app, entry, tab).is_some();
    let mobile = app.view.layout == crate::app::state::ViewLayout::Mobile;
    let control_pane =
        row_control_pane(app, entry, tab).filter(|control| control.snoozed || selected || mobile);
    let controls_width =
        selected_row_controls_width(control_pane.as_ref(), title_width, rect.width);
    if controls_width == 0 {
        return None;
    }
    let start = rect.x.saturating_add(
        (widths.prefix + SIDEBAR_DOT_FIELD_WIDTH + title_width - controls_width) as u16,
    );
    if column < start || column >= start.saturating_add(controls_width as u16) {
        return None;
    }
    let control = control_pane?;
    if column < start.saturating_add(SIDEBAR_SNOOZE_CONTROL_WIDTH as u16) {
        Some(crate::app::state::SidebarHoverAction::Snooze {
            target: control.target,
        })
    } else if control.show_settle {
        Some(crate::app::state::SidebarHoverAction::Settle {
            target: control.target,
        })
    } else {
        None
    }
}

pub(crate) fn selected_remote_row_control_at(
    app: &AppState,
    entry: &RemoteAgentPanelEntry,
    rect: Rect,
    depth: u16,
    _show_host_identity: bool,
    column: u16,
) -> Option<crate::app::state::SidebarHoverAction> {
    let requested_prefix = usize::from(depth) * 3 + 1;
    let total_width = usize::from(rect.width);
    let row_width = total_width;
    let title = compact_row_title_for_width(
        &entry.render_title,
        &entry.render_provider,
        row_width,
        requested_prefix,
    );
    let widths = compact_row_widths(title, &entry.render_provider, row_width, requested_prefix);
    let fixed_width = widths.prefix
        + SIDEBAR_DOT_FIELD_WIDTH
        + widths.provider
        + SIDEBAR_MACHINE_FIELD_WIDTH
        + widths.age;
    let title_width = row_width.saturating_sub(fixed_width);
    let selected = app
        .sidebar_selected_remote_agent
        .as_ref()
        .is_some_and(|selected| selected == &entry.agent_ref);
    let mobile = app.view.layout == crate::app::state::ViewLayout::Mobile;
    let control = remote_row_control(entry).filter(|control| control.snoozed || selected || mobile);
    let controls_width = selected_row_controls_width(control.as_ref(), title_width, rect.width);
    if controls_width == 0 {
        return None;
    }
    let start = rect.x.saturating_add(
        (widths.prefix + SIDEBAR_DOT_FIELD_WIDTH + title_width - controls_width) as u16,
    );
    if column < start || column >= start.saturating_add(controls_width as u16) {
        return None;
    }
    let control = control?;
    if column < start.saturating_add(SIDEBAR_SNOOZE_CONTROL_WIDTH as u16) {
        Some(crate::app::state::SidebarHoverAction::Snooze {
            target: control.target,
        })
    } else if control.show_settle {
        Some(crate::app::state::SidebarHoverAction::Settle {
            target: control.target,
        })
    } else {
        None
    }
}

