pub(crate) struct AgentReplyTimestamp {
    pub(crate) instant: std::time::Instant,
    pub(crate) unix_seconds: u64,
}

#[derive(Clone)]
#[allow(dead_code)]
pub(crate) struct AgentPanelEntryData {
    pub primary_label: String,
    /// Server-owned Space label. Grouping views render this in the existing
    /// trailing tag cell instead of deriving a label from the pane title.
    pub space_label: String,
    pub primary_tab_label: Option<String>,
    pub tab_has_custom_name: bool,
    pub tab_label_leads_with_agent: bool,
    pub pane_label: Option<String>,
    pub pane_label_is_agent_identity: bool,
    pub terminal_title: Option<String>,
    pub terminal_title_stripped: Option<String>,
    pub agent_label: Option<String>,
    pub agent_kind_label: Option<String>,
    pub agent: Option<crate::detect::Agent>,
    pub foreground_process_name: Option<String>,
    /// Current or most recently exited provider, used only to detect
    /// ambiguous multi-pane rollups. Rendering still uses `agent` so an exited
    /// provider never leaves a stale suffix on a single-pane row.
    pub agent_context: Option<crate::detect::Agent>,
    /// At least one pane in this row is agent-backed. This stays true for a
    /// rolled-up tab whose panes have conflicting providers, while `agent`
    /// becomes `None` so the provider suffix is not misleading.
    pub has_agent: bool,
    pub prio: bool,
    /// User-set focus star on the owning tab. Rendering only: it never
    /// reorders or regroups the row.
    pub starred: bool,
    pub state: AgentState,
    /// Runtime-derived human-attention severity. `None` means an older source
    /// omitted the projection; `Some(AttentionTier::None)` explicitly clears it.
    pub attention_tier: Option<AttentionTier>,
    /// The last closing-block report still names at least one gate, even if
    /// the lifecycle state has moved on. It becomes a red blocker dot once the
    /// pane stops working.
    pub open_blockers: bool,
    pub completion_tier: Option<CompletionTier>,
    /// The pane's agent stopped on an exhausted plan usage/rate limit. Nobody
    /// can answer it, so it reads as its own red "usage" label rather than a
    /// gate or a lifecycle state.
    pub usage_limited: bool,
    /// Positive count from the current sub-agent source. Rendering depends on
    /// this field only so the source can change without changing row layout.
    pub active_subagents: Option<u32>,
    /// Small-capital model letter from `model_letter_for`, drawn plain right
    /// after the agent icon. Local panes only; remote rows carry `None`.
    pub model_letter: Option<&'static str>,
    pub waiting_on_agents: bool,
    pub holds_shell: bool,
    pub gate_count: usize,
    pub seen: bool,
    pub done_since: Option<std::time::Instant>,
    pub stale: bool,
    pub reported_at: Option<std::time::Instant>,
    pub last_agent_state_change_seq: Option<u64>,
    pub activity_at: Option<std::time::Instant>,
    pub state_labels: std::collections::HashMap<String, String>,
    pub tokens: std::collections::HashMap<String, String>,
    /// First pane in canonical layout order for its tab. The renderer uses it
    /// to project the tab row exactly once before its pane children.
    pub tab_first_pane: bool,
    /// Fleet host this pane is attached to over ssh. The pane lives in the
    /// local list, so the row names the machine next to the provider.
    pub remote_host: Option<String>,
}

impl AgentPanelEntry {
    pub(crate) fn new(identity: AgentPanelIdentity, data: AgentPanelEntryData) -> Self {
        Self {
            identity,
            last_turn_at: None,
            data: std::sync::Arc::new(data),
            pinned: false,
            space_label_redundant: false,
            remote_entry: None,
            remote_show_host_identity: false,
            pending_ask: None,
            working_shelf: false,
            pod: None,
        }
    }

    pub(crate) fn local_target(&self) -> Option<AgentPanelLocalTarget> {
        match self.identity {
            AgentPanelIdentity::Local(target) => Some(target),
            AgentPanelIdentity::Remote(_) => None,
        }
    }
}

fn pending_ask_from_items(
    gates: &[crate::api::schema::ClosingBlockItem],
    items: &[crate::api::schema::ClosingBlockItem],
) -> Option<String> {
    let text = gates
        .iter()
        .chain(items)
        .find(|item| item.requires_human_input())
        .and_then(|item| item.text.lines().next())
        .map(|line| {
            line.chars()
                .filter(|character| !character.is_control())
                .take(256)
                .collect::<String>()
        })?;
    let text = text.trim();
    (!text.is_empty()).then(|| text.to_string())
}

fn pending_human_ask(terminal: &crate::terminal::TerminalState) -> Option<String> {
    pending_ask_from_items(terminal.closing_gates(), terminal.closing_items())
}

pub(super) fn visible_pending_ask<'a>(
    app: &AppState,
    entry: &'a AgentPanelEntry,
) -> Option<&'a str> {
    (app.sidebar_sections_layout && app.sidebar_show_ask_subtitles && entry_is_blocked(entry))
        .then_some(entry.pending_ask.as_deref())
        .flatten()
}

impl std::ops::Deref for AgentPanelEntry {
    type Target = AgentPanelEntryData;

    fn deref(&self) -> &Self::Target {
        &self.data
    }
}

impl std::ops::DerefMut for AgentPanelEntry {
    fn deref_mut(&mut self) -> &mut Self::Target {
        debug_assert!(
            self.remote_entry.is_none(),
            "cached remote row data must stay immutable during projection"
        );
        #[cfg(test)]
        if self.remote_entry.is_some() && std::sync::Arc::strong_count(&self.data) > 1 {
            REMOTE_AGENT_PANEL_DATA_COPIES.with(|copies| copies.set(copies.get() + 1));
        }
        std::sync::Arc::make_mut(&mut self.data)
    }
}

#[cfg(test)]
thread_local! {
    static REMOTE_AGENT_PANEL_DATA_COPIES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
fn take_remote_agent_panel_data_copies() -> usize {
    REMOTE_AGENT_PANEL_DATA_COPIES.with(|copies| copies.replace(0))
}

