    #[test]
    fn a_pane_attached_to_a_fleet_host_shows_machine_after_provider() {
        let mut app = app_with_agents(&["attached"]);
        app.nerd_font = false;
        app.fleet_snapshot = crate::fleet::Snapshot {
            polled: true,
            configured_hosts: vec!["ub1".into()],
            hosts: vec![fleet_host_snapshot("ub1", false, Vec::new())],
            ..crate::fleet::Snapshot::default()
        };
        let pane_id = app.workspaces[0].tabs[0].root_pane;
        let terminal_id = app.workspaces[0].tabs[0].panes[&pane_id]
            .attached_terminal_id
            .clone();
        let terminal = app.terminals.get_mut(&terminal_id).unwrap();
        terminal.detected_agent = Some(Agent::Claude);
        terminal.launch_argv = Some(vec![
            "ssh".into(),
            "-t".into(),
            "ub1".into(),
            "herdr agent attach 'w1:p1'".into(),
        ]);
        let entry = sidebar_thread_entries(&app)
            .into_iter()
            .next()
            .expect("attached entry");
        assert_eq!(entry.remote_host.as_deref(), Some("ub1"));
        let provider = compact_provider(&entry, false);
        assert_eq!(provider, "cc");

        let width = 40;
        let mut terminal = Terminal::new(TestBackend::new(width, 1)).unwrap();
        terminal
            .draw(|frame| {
                render_compact_agent_row_with_prefix(
                    &app,
                    frame,
                    &entry,
                    Rect::new(0, 0, width, 1),
                    0,
                    false,
                    None,
                    None,
                )
            })
            .unwrap();
        let rendered = row_text(terminal.backend().buffer(), 0, width);
        assert!(rendered.contains("cc ub1"), "{rendered:?}");

        // Search still matches the host even though its row shows only a short label.
        app.sidebar_work_filter.query = "ub1".into();
        assert_eq!(sidebar_filtered_agent_entries_from(&app, None).len(), 1);
        app.sidebar_work_filter.query = "ub9".into();
        assert!(sidebar_filtered_agent_entries_from(&app, None).is_empty());

        // A tab that mixes the attached pane with a local one names no machine.
        let mut local = entry.clone();
        let target = entry.local_target().unwrap();
        local.identity = AgentPanelIdentity::Local(AgentPanelLocalTarget {
            pane_id: crate::layout::PaneId::from_raw(target.pane_id.raw() + 1),
            ..target
        });
        local.remote_host = None;
        let same = aggregate_tab_entries(&[entry.clone(), entry.clone()]);
        assert_eq!(
            same.values().next().unwrap().remote_host.as_deref(),
            Some("ub1")
        );
        let mixed = aggregate_tab_entries(&[entry, local]);
        assert_eq!(mixed.values().next().unwrap().remote_host, None);
    }

    #[test]
    fn remote_rows_render_the_host_title_and_fall_back_to_the_handle() {
        let mut titled = remote_agent_info(
            "w23:p1D",
            "cl-ceea66cc",
            crate::api::schema::AgentStatus::Working,
            false,
            false,
        );
        titled.terminal_title_stripped = Some("Scalable V2 cost levers handoff".into());
        titled.work_context.work_title = Some("lower-priority work title".into());
        let untitled = remote_agent_info(
            "w23:p1E",
            "cl-deadbeef",
            crate::api::schema::AgentStatus::Idle,
            false,
            false,
        );
        let snapshot = crate::fleet::Snapshot {
            hosts: vec![fleet_host_snapshot(
                "ub1",
                false,
                vec![
                    crate::fleet::FleetRow::test_agent_info_row("ub1", titled),
                    crate::fleet::FleetRow::test_agent_info_row("ub1", untitled),
                ],
            )],
            ..crate::fleet::Snapshot::default()
        };
        let entries = remote_agent_panel_entries(&snapshot, false);
        let app = AppState::test_new();
        assert_eq!(
            snapshot.hosts[0].entries[0].title.as_deref(),
            Some("Scalable V2 cost levers handoff")
        );
        assert_eq!(
            entries[0].entry.pane_label.as_deref(),
            Some("Scalable V2 cost levers handoff")
        );
        assert_eq!(entries[0].render_title, "Scalable V2 cost levers handoff");
        assert_eq!(entries[1].render_title, "cl-deadbeef");

        for (entry, expected) in entries
            .iter()
            .zip(["Scalable V2 cost levers handoff", "cl-deadbeef"])
        {
            let mut terminal = Terminal::new(TestBackend::new(80, 1)).unwrap();
            terminal
                .draw(|frame| {
                    render_remote_compact_agent_row(
                        &app,
                        frame,
                        entry,
                        Rect::new(0, 0, 80, 1),
                        1,
                        None,
                    )
                })
                .unwrap();
            let rendered = row_text(terminal.backend().buffer(), 0, 80);
            assert!(rendered.contains("ub1"), "{rendered:?}");
            assert!(!rendered.contains(" · ub1"), "{rendered:?}");
            assert!(rendered.contains(expected), "{rendered:?}");
        }
    }

