    #[test]
    fn remote_projection_preserves_config_order_and_blocked_semantics() {
        let snapshot = crate::fleet::Snapshot {
            polled: true,
            configured_hosts: vec!["remote-b".into(), "local".into(), "remote-a".into()],
            hosts: vec![
                fleet_host_snapshot(
                    "remote-b",
                    false,
                    vec![
                        crate::fleet::FleetRow::test_agent_info_row(
                            "remote-b",
                            remote_agent_info(
                                "pane/1",
                                "working gate",
                                crate::api::schema::AgentStatus::Working,
                                true,
                                false,
                            ),
                        ),
                        crate::fleet::FleetRow::test_agent_info_row(
                            "remote-b",
                            remote_agent_info(
                                "pane/2",
                                "idle gate",
                                crate::api::schema::AgentStatus::Idle,
                                true,
                                false,
                            ),
                        ),
                    ],
                ),
                fleet_host_snapshot(
                    "local",
                    true,
                    vec![crate::fleet::FleetRow::test_agent_info_row(
                        "local",
                        remote_agent_info(
                            "pane/3",
                            "local row",
                            crate::api::schema::AgentStatus::Blocked,
                            false,
                            false,
                        ),
                    )],
                ),
                fleet_host_snapshot(
                    "remote-a",
                    false,
                    vec![
                        crate::fleet::FleetRow::test_agent_info_row(
                            "remote-a",
                            remote_agent_info(
                                "pane/4",
                                "usage stop",
                                crate::api::schema::AgentStatus::Idle,
                                false,
                                true,
                            ),
                        ),
                        crate::fleet::FleetRow::test_run_row("remote-a", "ra-windowless", true),
                    ],
                ),
            ],
            ..crate::fleet::Snapshot::default()
        };

        let entries = remote_agent_panel_entries(&snapshot, false);
        let cloned_entry = entries[0].entry.clone();
        assert!(std::sync::Arc::ptr_eq(
            &entries[0].entry.data,
            &cloned_entry.data
        ));
        let aggregated = aggregate_tab_entries(std::slice::from_ref(&entries[0].entry));
        let aggregated_entry = aggregated
            .get(&SidebarEntryKey::Remote(entries[0].agent_ref.clone()))
            .expect("remote projection survives row aggregation");
        assert!(std::sync::Arc::ptr_eq(
            &entries[0].entry.data,
            &aggregated_entry.data
        ));
        assert_eq!(
            entries
                .iter()
                .map(|entry| entry.agent_ref.to_string())
                .collect::<Vec<_>>(),
            ["remote-b::pane/1", "remote-b::pane/2", "remote-a::pane/4"]
        );
        assert!(entries.iter().all(|entry| matches!(
            &entry.entry.identity,
            AgentPanelIdentity::Remote(agent_ref) if agent_ref == &entry.agent_ref
        )));
        assert!(!entry_is_blocked(&entries[0]));
        assert!(entry_is_blocked(&entries[1]));
        assert!(entry_is_blocked(&entries[2]));

        let mut app = app_with_agents(&["local"]);
        app.remote_agent_panel_entries = entries.clone();
        expand_fleet(&mut app);
        let rows = sidebar_rows(&app);
        for entry in &entries {
            let projected = rows
                .iter()
                .find_map(|row| match row {
                    SidebarRow::RemoteAgent {
                        entry: projected, ..
                    } if projected.agent_ref == entry.agent_ref => Some(projected),
                    _ => None,
                })
                .expect("projected remote row");
            assert!(std::sync::Arc::ptr_eq(entry, projected));
        }
        assert!(!rows.iter().any(|row| {
            matches!(row, SidebarRow::SectionHeader { title, .. } if *title == "Blocked")
        }));
        let last_local = rows
            .iter()
            .rposition(|row| matches!(row, SidebarRow::Tab { .. } | SidebarRow::Agent { .. }))
            .expect("local row");
        let first_remote = rows
            .iter()
            .position(|row| matches!(row, SidebarRow::RemoteAgent { .. }))
            .expect("remote row");
        assert!(
            last_local < first_remote,
            "all local rows must precede remote hosts"
        );
        assert_eq!(
            rows.iter()
                .filter_map(|row| match row {
                    SidebarRow::RemoteAgent { entry, .. } => {
                        Some(entry.agent_ref.to_string())
                    }
                    _ => None,
                })
                .collect::<Vec<_>>(),
            entries
                .iter()
                .map(|entry| entry.agent_ref.to_string())
                .collect::<Vec<_>>()
        );

        app.blocked_filter = true;
        let blocked_rows = sidebar_rows(&app);
        assert!(blocked_rows.iter().all(
            |row| !matches!(row, SidebarRow::SectionHeader { title, .. } if *title == "Blocked")
        ));
        assert_eq!(
            blocked_rows
                .iter()
                .filter_map(|row| match row {
                    SidebarRow::RemoteAgent { entry, .. } => Some(entry.agent_ref.agent.as_str()),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            ["pane/2", "pane/4"]
        );
    }

