    #[test]
    fn active_title_color_steps_away_from_the_panel_and_preserves_terminal_fallbacks() {
        // ac3: the selected title moves one third away from the panel
        // background -- darker on a light panel, brighter on a dark one -- so
        // the same rule reads as emphasis in both appearances. Bold supplies
        // the weight; the foreground supplies the contrast.
        let one_light = crate::app::state::Palette::one_light();
        assert_eq!(
            active_sidebar_title_color(&one_light),
            Color::Rgb(37, 38, 44)
        );

        let one_dark = crate::app::state::Palette::one_dark();
        assert_eq!(
            active_sidebar_title_color(&one_dark),
            Color::Rgb(199, 203, 212)
        );

        let terminal = crate::app::state::Palette::terminal();
        assert_eq!(active_sidebar_title_color(&terminal), terminal.text);

        let mut custom_reset = crate::app::state::Palette::one_light();
        custom_reset.panel_bg = Color::Reset;
        custom_reset.text = Color::Rgb(12, 34, 56);
        assert_eq!(active_sidebar_title_color(&custom_reset), custom_reset.text);
    }

    /// The regression this fixes: on every dark palette the selected Space and
    /// the current tab title were the *dimmest* text in the sidebar, below the
    /// unselected rows they had to stand out from.
    #[test]
    fn active_title_outshines_unselected_rows_on_every_dark_palette() {
        let luminance = |color: Color| match color {
            Color::Rgb(r, g, b) => u32::from(r) * 299 + u32::from(g) * 587 + u32::from(b) * 114,
            other => panic!("expected an rgb color, got {other:?}"),
        };

        for palette in [
            crate::app::state::Palette::github_dark_high_contrast(),
            crate::app::state::Palette::one_dark(),
            crate::app::state::Palette::catppuccin(),
        ] {
            let selected = luminance(active_sidebar_title_color(&palette));
            assert!(
                selected > luminance(palette.subtext0),
                "selected title must outshine the unselected rows"
            );
            assert!(
                selected > luminance(palette.text),
                "selected title must outshine the authored text token"
            );
        }

        assert_eq!(
            active_sidebar_title_color(&crate::app::state::Palette::github_dark_high_contrast()),
            Color::Rgb(245, 247, 249)
        );
    }

    fn blended_test_color(foreground: Color, background: Color, opacity: u8) -> Color {
        let foreground = crate::app::state::color_rgb(foreground).expect("known foreground");
        let background = crate::app::state::color_rgb(background).expect("known background");
        let blend = |foreground: u8, background: u8| {
            ((u16::from(foreground) * u16::from(opacity)
                + u16::from(background) * u16::from(100 - opacity)
                + 50)
                / 100) as u8
        };
        Color::Rgb(
            blend(foreground.r, background.r),
            blend(foreground.g, background.g),
            blend(foreground.b, background.b),
        )
    }

    #[test]
    fn working_row_opacity_matches_each_level_for_local_and_remote_at_18_and_60_columns() {
        let mut app = AppState::test_new();
        app.nerd_font = false;
        let mut working = compact_test_entry("working task", Some(Agent::Claude));
        working.state = AgentState::Working;
        let agent_ref =
            crate::api::schema::AgentRef::new("ub2", "pane/1").expect("valid remote reference");
        let remote = RemoteAgentPanelEntry::new(agent_ref, working.clone());
        let background = app.palette.sidebar_background();

        for opacity in [100, 75, 50, 25] {
            app.working_row_opacity_percent = opacity;
            let expected_dot = blended_test_color(app.palette.blue, background, opacity);
            let expected_title = blended_test_color(app.palette.subtext0, background, opacity);
            let expected_provider = blended_test_color(
                crate::ui::icons::claude_color(&app.palette),
                background,
                opacity,
            );
            let expected_remote_suffix =
                blended_test_color(app.palette.overlay0, background, opacity);
            for width in [18, 60] {
                for is_remote in [false, true] {
                    let mut terminal = Terminal::new(TestBackend::new(width, 1)).unwrap();
                    terminal
                        .draw(|frame| {
                            let rect = Rect::new(0, 0, width, 1);
                            if is_remote {
                                render_remote_compact_agent_row_with_identity(
                                    &app, frame, &remote, rect, 0, None, true,
                                );
                            } else {
                                render_compact_agent_row(
                                    &app, frame, &working, rect, 0, true, None,
                                );
                            }
                        })
                        .unwrap();
                    let buffer = terminal.backend().buffer();
                    let rendered = row_text(buffer, 0, width);
                    let dot_x = find_symbol_x(buffer, 0, width, "●");
                    let title_x = find_symbol_x(buffer, 0, width, "w");
                    assert!(dot_x < title_x, "{rendered:?}");
                    assert_eq!(buffer[(dot_x, 0)].style().fg, Some(expected_dot));
                    assert_eq!(buffer[(title_x, 0)].style().fg, Some(expected_title));
                    let machine = if is_remote { "u" } else { "l" };
                    let machine_x = find_symbol_x(buffer, 0, width, machine);
                    assert_eq!(
                        buffer[(machine_x, 0)].style().fg,
                        Some(expected_remote_suffix)
                    );
                    assert!(!rendered.contains("· ub2"), "{rendered:?}");
                    if width == 60 {
                        let provider_x = find_symbol_x(buffer, 0, width, "c");
                        assert_eq!(buffer[(provider_x, 0)].style().fg, Some(expected_provider));
                        assert!(provider_x < machine_x, "{rendered:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn terminal_palette_keeps_every_working_opacity_level_distinct() {
        let mut app = AppState::test_new();
        app.palette = crate::app::state::Palette::terminal();
        let mut working = compact_test_entry("working task", Some(Agent::Claude));
        working.state = AgentState::Working;
        let agent_ref =
            crate::api::schema::AgentRef::new("ub2", "pane/1").expect("valid remote reference");
        let remote = RemoteAgentPanelEntry::new(agent_ref, working.clone());
        let mut rendered_levels = Vec::new();

        for opacity in [100, 75, 50, 25] {
            app.working_row_opacity_percent = opacity;
            let mut level = Vec::new();
            for is_remote in [false, true] {
                let mut terminal = Terminal::new(TestBackend::new(40, 1)).unwrap();
                terminal
                    .draw(|frame| {
                        if is_remote {
                            render_remote_compact_agent_row(
                                &app,
                                frame,
                                &remote,
                                Rect::new(0, 0, 40, 1),
                                0,
                                None,
                            );
                        } else {
                            render_compact_agent_row(
                                &app,
                                frame,
                                &working,
                                Rect::new(0, 0, 40, 1),
                                0,
                                false,
                                None,
                            );
                        }
                    })
                    .unwrap();
                let buffer = terminal.backend().buffer();
                let dot_x = find_symbol_x(buffer, 0, 40, "●");
                let title_x = find_symbol_x(buffer, 0, 40, "w");
                level.push((
                    buffer[(dot_x, 0)].style().fg,
                    buffer[(title_x, 0)].style().fg,
                ));
            }
            assert_eq!(level[0], level[1], "local and remote differ at {opacity}%");
            rendered_levels.push(level[0]);
        }

        for (index, level) in rendered_levels.iter().enumerate() {
            assert!(
                !rendered_levels[..index].contains(level),
                "opacity levels collapse at index {index}: {rendered_levels:?}"
            );
        }
    }

