    fn aggregation_entry(
        state: AgentState,
        seen: bool,
        foreground_process_name: Option<&str>,
        state_label: &str,
    ) -> AgentPanelEntry {
        let mut state_labels = std::collections::HashMap::new();
        state_labels.insert(
            agent_panel_status_key(state, seen).to_string(),
            state_label.to_string(),
        );
        AgentPanelEntry::new(
            AgentPanelIdentity::Local(AgentPanelLocalTarget {
                ws_idx: 0,
                tab_idx: 0,
                pane_id: crate::layout::PaneId::alloc(),
            }),
            AgentPanelEntryData {
                usage_limited: false,
                primary_label: "workspace".into(),
                space_label: String::new(),
                primary_tab_label: Some("tab".into()),
                tab_has_custom_name: false,
                tab_label_leads_with_agent: false,
                pane_label: None,
                pane_label_is_agent_identity: false,
                terminal_title: None,
                terminal_title_stripped: None,
                agent_label: None,
                agent_kind_label: None,
                agent: None,
                foreground_process_name: foreground_process_name.map(str::to_string),
                agent_context: None,
                has_agent: true,
                prio: true,
                starred: false,
                state,
                attention_tier: None,
                open_blockers: false,
                completion_tier: None,
                active_subagents: None,
                model_letter: None,
                waiting_on_agents: false,
                holds_shell: false,
                gate_count: 0,
                seen,
                done_since: None,
                stale: false,
                reported_at: None,
                last_agent_state_change_seq: None,
                activity_at: None,
                state_labels,
                tokens: std::collections::HashMap::new(),
                tab_first_pane: false,
                remote_host: None,
            },
        )
    }

    fn row_kinds(app: &AppState) -> Vec<(char, usize)> {
        sidebar_rows(app)
            .into_iter()
            .filter_map(|row| match row {
                SidebarRow::Workspace { ws_idx, .. } => Some(('w', ws_idx)),
                SidebarRow::Tab { entry, .. } => Some(('t', entry.local_target().unwrap().ws_idx)),
                SidebarRow::Agent { entry, .. } => {
                    Some(('a', entry.local_target().unwrap().ws_idx))
                }
                SidebarRow::RemoteAgent { .. } => Some(('r', 0)),
                SidebarRow::SectionHeader { title, .. } if title == SPACES_SECTION_TITLE => {
                    Some(('h', 0))
                }
                SidebarRow::NestedHeader { .. } => Some(('h', 0)),
                SidebarRow::SectionHeader { .. }
                | SidebarRow::PodHeader { .. }
                | SidebarRow::PodMember { .. }
                | SidebarRow::Divider
                | SidebarRow::ShelfDivider
                | SidebarRow::NeedsYou { .. }
                | SidebarRow::NeedsYouMore { .. }
                | SidebarRow::SymphonyJob { .. }
                | SidebarRow::SymphonyEmpty
                | SidebarRow::AgentRun { .. }
                | SidebarRow::AloopLoop { .. }
                | SidebarRow::AloopRunLine { .. }
                | SidebarRow::AloopFinding { .. }
                | SidebarRow::AloopCleanRuns { .. }
                | SidebarRow::AloopCleanRun { .. }
                | SidebarRow::AloopUnreachable { .. }
                | SidebarRow::AloopEmpty => None,
            })
            .collect()
    }

