    #[test]
    fn flattened_spaces_sidebar_uses_configured_status_symbols() {
        let mut app = app_with_agents(&["blocked", "done"]);
        app.status_indicators = StatusIndicatorStyle::Symbols;

        let first_pane = app.workspaces[0].tabs[0].root_pane;
        let first_terminal = app.workspaces[0].tabs[0].panes[&first_pane]
            .attached_terminal_id
            .clone();
        let second_pane = app.workspaces[1].tabs[0].root_pane;
        let second_terminal = app.workspaces[1].tabs[0].panes[&second_pane]
            .attached_terminal_id
            .clone();
        app.terminals
            .get_mut(&first_terminal)
            .unwrap()
            .set_raw_agent_state_for_test(AgentState::Blocked);
        let second_terminal_state = app.terminals.get_mut(&second_terminal).unwrap();
        second_terminal_state.set_raw_agent_state_for_test(AgentState::Idle);
        app.workspaces[1].tabs[0]
            .panes
            .get_mut(&second_pane)
            .unwrap()
            .seen = false;
        app.reconcile_sidebar_presentation();

        let area = Rect::new(0, 0, 32, 12);
        let mut terminal = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
        terminal
            .draw(|frame| render_sidebar(&app, &TerminalRuntimeRegistry::new(), frame, area))
            .unwrap();
        let text = (0..area.height)
            .map(|row| row_text(terminal.backend().buffer(), row, area.width - 1))
            .collect::<Vec<_>>();

        // Two shapes only: blocked and done-unread are both `○`, and the palette
        // separates them. Asserting the glyph alone would no longer distinguish them.
        assert!(text.iter().any(|line| line.contains('○')), "{text:?}");
        assert!(
            !text.iter().any(|line| line.contains('◆')),
            "done-unread must not reintroduce a third dot shape: {text:?}"
        );

        let buffer = terminal.backend().buffer();
        let dot_colors = (0..area.height)
            .filter_map(|row| {
                (0..area.width - 1)
                    .find(|x| buffer[(*x, row)].symbol() == "○")
                    .map(|x| buffer[(x, row)].style().fg)
            })
            .collect::<std::collections::HashSet<_>>();
        assert!(
            dot_colors.len() >= 2,
            "blocked and done-unread share a shape, so they must differ by colour: {dot_colors:?}"
        );
    }

    #[test]
    fn a_working_pane_with_persisted_gates_keeps_only_the_blue_working_dot() {
        let mut app = app_with_agents(&["one"]);
        let pane = app.workspaces[0].tabs[0].root_pane;
        let terminal_id = app.workspaces[0].terminal_id(pane).unwrap().clone();
        let terminal = app.terminals.get_mut(&terminal_id).unwrap();
        terminal.set_raw_agent_state_for_test(AgentState::Working);
        terminal.apply_closing_block_payload(
            vec![crate::api::schema::ClosingBlockItem {
                blocking: true,
                n: 1,
                label: "Gate".into(),
                text: "Approve the open PR".into(),
                pr: None,
                ticket: None,
                url: None,
                default: None,
                default_at: None,
            }],
            Vec::new(),
            Vec::new(),
        );
        app.reconcile_sidebar_presentation();

        let entry = sidebar_thread_entries(&app)
            .into_iter()
            .find(|entry| entry.local_target().unwrap().pane_id == pane)
            .expect("pane entry");
        assert!(entry.open_blockers);
        assert_eq!(entry.state, AgentState::Working);
        assert!(!entry_is_blocked(&entry));
        assert!(!gate_overrides_label(&entry));

        let layout = tab_row_layout(
            &entry,
            app.view_observed_at,
            60,
            4,
            &app.palette,
            app.status_indicators,
            false,
        );
        assert_eq!(layout.dot, "●");
        assert_eq!(
            agent_panel_label_color(&entry, &app.palette),
            app.palette.blue
        );

        for width in [18, 60] {
            let area = Rect::new(0, 0, width, 12);
            let mut rendered = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
            rendered
                .draw(|frame| render_sidebar(&app, &TerminalRuntimeRegistry::new(), frame, area))
                .unwrap();
            let buffer = rendered.backend().buffer();
            let colored_dots = |color| {
                (0..area.height)
                    .flat_map(|y| (0..area.width).map(move |x| (x, y)))
                    .filter(|(x, y)| {
                        let cell = &buffer[(*x, *y)];
                        cell.symbol() == "●" && cell.fg == color
                    })
                    .count()
            };
            assert_eq!(colored_dots(app.palette.red), 0, "width {width}");
            assert_eq!(colored_dots(app.palette.blue), 1, "width {width}");
        }

        // Clearing the gate does not change the already-correct working row.
        let terminal = app.terminals.get_mut(&terminal_id).unwrap();
        terminal.apply_closing_block_payload(Vec::new(), Vec::new(), Vec::new());
        let entry = sidebar_thread_entries(&app)
            .into_iter()
            .find(|entry| entry.local_target().unwrap().pane_id == pane)
            .expect("pane entry");
        assert!(!entry.open_blockers);
    }

    #[test]
    fn closing_items_render_at_their_runtime_attention_tier() {
        let mut app = app_with_agents(&["gate", "items", "mixed", "resumed"]);
        let item = |label: &str| crate::api::schema::ClosingBlockItem {
            blocking: true,
            n: 1,
            label: label.into(),
            text: "Needs the human".into(),
            pr: None,
            ticket: None,
            url: None,
            default: None,
            default_at: None,
        };
        for (ws_idx, gates, items, state) in [
            (0, vec![item("Gate")], Vec::new(), AgentState::Blocked),
            (1, Vec::new(), vec![item("Answer")], AgentState::Blocked),
            (
                2,
                vec![item("Gate")],
                vec![item("Verify")],
                AgentState::Blocked,
            ),
            (3, Vec::new(), vec![item("Answer")], AgentState::Working),
        ] {
            let pane = app.workspaces[ws_idx].tabs[0].root_pane;
            let terminal_id = app.workspaces[ws_idx].terminal_id(pane).unwrap().clone();
            let terminal = app.terminals.get_mut(&terminal_id).unwrap();
            terminal.set_raw_agent_state_for_test(state);
            terminal.apply_closing_block_payload(gates, items, Vec::new());
        }

        let entries = sidebar_thread_entries(&app);
        let entry = |ws_idx| {
            entries
                .iter()
                .find(|entry| entry.local_target().unwrap().ws_idx == ws_idx)
                .unwrap()
        };
        assert_eq!(compact_row_color(entry(0), &app.palette), app.palette.red);
        assert_eq!(compact_row_color(entry(1), &app.palette), app.palette.red);
        assert_ne!(app.palette.peach, app.palette.yellow);
        assert_eq!(compact_row_color(entry(2), &app.palette), app.palette.red);
        assert_eq!(
            compact_row_color(entry(3), &app.palette),
            app.palette.blue,
            "the yellow tier clears when the agent resumes working"
        );

        let attention_pane = app.workspaces[1].tabs[0].root_pane;
        app.workspaces[1].tabs[0]
            .panes
            .get_mut(&attention_pane)
            .unwrap()
            .settled_at = Some(1);
        assert_eq!(
            app.workspaces[1]
                .aggregate_state_and_attention(&app.terminals)
                .2,
            AttentionTier::None,
            "settled panes leave the workspace attention roll-up"
        );
    }

