    #[test]
    fn priority_agent_panel_sort_uses_attention_then_space_order() {
        let mut app = crate::app::state::AppState::test_new();
        app.workspaces = vec![
            Workspace::test_new("one"),
            Workspace::test_new("two"),
            Workspace::test_new("three"),
            Workspace::test_new("four"),
        ];
        app.ensure_test_terminals();
        app.active = Some(0);
        app.selected = 0;
        app.agent_panel_sort = crate::app::state::AgentPanelSort::Priority;

        let set_state = |app: &mut crate::app::state::AppState, ws_idx: usize, state| {
            let pane = app.workspaces[ws_idx].tabs[0].root_pane;
            let terminal_id = app.workspaces[ws_idx].tabs[0].panes[&pane]
                .attached_terminal_id
                .clone();
            let terminal = app.terminals.get_mut(&terminal_id).unwrap();
            terminal.detected_agent = Some(Agent::Claude);
            terminal.set_raw_agent_state_for_test(state);
        };
        set_state(&mut app, 0, AgentState::Working);
        set_state(&mut app, 1, AgentState::Idle);
        set_state(&mut app, 2, AgentState::Working);
        set_state(&mut app, 3, AgentState::Blocked);

        let done_pane = app.workspaces[1].tabs[0].root_pane;
        app.workspaces[1].tabs[0]
            .panes
            .get_mut(&done_pane)
            .unwrap()
            .seen = false;

        let labels: Vec<String> = agent_panel_entries(&app)
            .into_iter()
            .map(|entry| entry.primary_label.clone())
            .collect();

        assert_eq!(labels, ["four", "two", "one", "three"]);
    }

    /// Describe the priority projection as `("section", title)` / `("agent",
    /// workspace)` pairs, so a test can assert grouping and order together.
    fn priority_row_shape(app: &AppState) -> Vec<(&'static str, String)> {
        sidebar_rows(app)
            .into_iter()
            .filter_map(|row| match row {
                SidebarRow::SectionHeader { title, .. } if title == SPACES_SECTION_TITLE => {
                    Some(("section", title.to_string()))
                }
                SidebarRow::Agent { entry, .. } => Some(("agent", entry.primary_label.clone())),
                SidebarRow::RemoteAgent { entry, .. } => {
                    Some(("remote", entry.agent_ref.to_string()))
                }
                SidebarRow::Workspace { .. } => Some(("workspace", String::new())),
                SidebarRow::Tab { .. } => Some(("tab", String::new())),
                SidebarRow::NestedHeader { title, .. } => Some(("section", title)),
                SidebarRow::SectionHeader { .. }
                | SidebarRow::PodHeader { .. }
                | SidebarRow::PodMember { .. }
                | SidebarRow::Divider
                | SidebarRow::ShelfDivider
                | SidebarRow::NeedsYou { .. }
                | SidebarRow::NeedsYouMore { .. }
                | SidebarRow::SymphonyJob { .. }
                | SidebarRow::SymphonyEmpty
                | SidebarRow::AgentRun { .. }
                | SidebarRow::AloopLoop { .. }
                | SidebarRow::AloopRunLine { .. }
                | SidebarRow::AloopFinding { .. }
                | SidebarRow::AloopCleanRuns { .. }
                | SidebarRow::AloopCleanRun { .. }
                | SidebarRow::AloopUnreachable { .. }
                | SidebarRow::AloopEmpty => None,
            })
            .collect()
    }

    fn priority_app_with_states(states: &[AgentState]) -> AppState {
        let mut app = crate::app::state::AppState::test_new();
        app.workspaces = states
            .iter()
            .enumerate()
            .map(|(idx, _)| Workspace::test_new(&format!("ws{idx}")))
            .collect();
        app.ensure_test_terminals();
        app.active = Some(0);
        app.selected = 0;
        app.agent_panel_sort = crate::app::state::AgentPanelSort::Priority;
        for (ws_idx, state) in states.iter().enumerate() {
            let pane = app.workspaces[ws_idx].tabs[0].root_pane;
            let terminal_id = app.workspaces[ws_idx].tabs[0].panes[&pane]
                .attached_terminal_id
                .clone();
            let terminal = app.terminals.get_mut(&terminal_id).unwrap();
            terminal.detected_agent = Some(Agent::Claude);
            terminal.set_raw_agent_state_for_test(*state);
        }
        app
    }

    #[test]
    fn a_pane_with_an_unanswered_gate_is_never_hidden_as_done() {
        let done_since = std::time::Instant::now();
        let mut app = priority_app_with_states(&[AgentState::Idle]);
        let pane_id = app.workspaces[0].tabs[0].root_pane;
        let terminal_id = app.workspaces[0].tabs[0].panes[&pane_id]
            .attached_terminal_id
            .clone();
        let pane = app.workspaces[0].tabs[0].panes.get_mut(&pane_id).unwrap();
        pane.seen = false;
        pane.done_since = Some(done_since);
        app.hide_done_after = std::time::Duration::from_secs(30 * 60);
        app.terminals.get_mut(&terminal_id).unwrap().closing_gates =
            vec![crate::api::schema::ClosingBlockItem {
                blocking: true,
                n: 1,
                label: "Gate".into(),
                text: "Choose the release path".into(),
                pr: None,
                ticket: None,
                url: None,
                default: None,
                default_at: None,
            }];

        app.view_observed_at =
            done_since + app.hide_done_after + std::time::Duration::from_secs(60);
        let rows = sidebar_rows(&app);
        assert!(
            !rows.iter().any(|row| matches!(
                row,
                SidebarRow::SectionHeader { title, count: 1.., .. } if *title == SETTLED_SECTION_TITLE
            )),
            "a pane waiting on a human must not be filed under Settled"
        );
        assert!(
            rows.iter().any(|row| matches!(row, SidebarRow::Tab { .. })),
            "and it must stay visible as a row"
        );
    }

    #[test]
    fn done_pane_moves_to_settled_only_after_hide_threshold() {
        let done_since = std::time::Instant::now();
        let mut app = priority_app_with_states(&[AgentState::Idle]);
        let pane_id = app.workspaces[0].tabs[0].root_pane;
        let pane = app.workspaces[0].tabs[0].panes.get_mut(&pane_id).unwrap();
        pane.seen = false;
        pane.done_since = Some(done_since);
        app.hide_done_after = std::time::Duration::from_secs(30 * 60);

        app.view_observed_at = done_since + app.hide_done_after;
        let boundary = sidebar_rows(&app);
        assert!(!boundary.iter().any(|row| matches!(
            row,
            SidebarRow::SectionHeader { title, count: 1.., .. }
                if *title == SETTLED_SECTION_TITLE
        )));
        assert!(boundary
            .iter()
            .any(|row| matches!(row, SidebarRow::Tab { .. })));

        app.view_observed_at += std::time::Duration::from_nanos(1);
        let hidden = sidebar_rows(&app);
        assert!(hidden.iter().any(|row| matches!(
            row,
            SidebarRow::SectionHeader {
                title,
                count: 1,
                collapsed: true,
                ..
            } if *title == SETTLED_SECTION_TITLE
        )));
        assert!(!hidden
            .iter()
            .any(|row| matches!(row, SidebarRow::Tab { .. })));

        app.collapsed_sidebar_groups.remove("repo:Settled");
        let expanded = sidebar_rows(&app);
        assert!(expanded
            .iter()
            .any(|row| matches!(row, SidebarRow::Tab { .. })));
    }

    #[test]
    fn sections_pinned_done_tab_stays_pinned_after_done_hide_threshold() {
        let done_since = std::time::Instant::now();
        let mut app = priority_app_with_states(&[AgentState::Idle]);
        app.sidebar_sections_layout = true;
        app.workspaces[0].tabs[0].pinned = true;
        let pane_id = app.workspaces[0].tabs[0].root_pane;
        let pane = app.workspaces[0].tabs[0].panes.get_mut(&pane_id).unwrap();
        pane.seen = false;
        pane.done_since = Some(done_since);
        app.hide_done_after = std::time::Duration::from_secs(30 * 60);
        app.view_observed_at =
            done_since + app.hide_done_after + std::time::Duration::from_nanos(1);
        set_sections_group_collapsed(&mut app, SETTLED_SECTION_TITLE, false);

        let pinned_rows = sidebar_rows(&app);
        let active_space = pinned_rows
            .iter()
            .position(|row| matches!(row, SidebarRow::Workspace { ws_idx: 0, .. }))
            .expect("active Space");
        let pinned_tab = pinned_rows
            .iter()
            .position(|row| {
                matches!(row, SidebarRow::Tab { entry, .. }
                if entry.local_target().is_some_and(|target| target.pane_id == pane_id))
            })
            .expect("pinned tab row");
        assert!(active_space < pinned_tab);
        assert!(!pinned_rows.iter().any(|row| matches!(
            row,
            SidebarRow::SectionHeader {
                title: PINNED_SECTION_TITLE,
                ..
            }
        )));
        assert!(pinned_rows.iter().any(|row| matches!(
            row,
            SidebarRow::SectionHeader { title, count: 0, .. }
                if *title == SETTLED_SECTION_TITLE
        )));

        app.workspaces[0].tabs[0].pinned = false;
        let unpinned_rows = sidebar_rows(&app);
        let settled_header = unpinned_rows
            .iter()
            .position(|row| matches!(row, SidebarRow::SectionHeader { title, .. } if *title == SETTLED_SECTION_TITLE))
            .expect("Settled shelf");
        let settled_tab = unpinned_rows
            .iter()
            .position(|row| {
                matches!(row, SidebarRow::Tab { entry, .. }
                if entry.local_target().is_some_and(|target| target.pane_id == pane_id))
            })
            .expect("settled tab row");
        assert!(settled_header < settled_tab);
        assert!(unpinned_rows.iter().any(|row| matches!(
            row,
            SidebarRow::SectionHeader { title, count: 1, .. }
                if *title == SETTLED_SECTION_TITLE
        )));
    }

