    #[test]
    fn repo_view_keeps_owner_repo_and_elides_it_at_minimum_width() {
        let mut app = AppState::test_new();
        app.workspaces = vec![Workspace::test_new("repo")];
        app.ensure_test_terminals();
        replace_tab_context(
            &mut app,
            0,
            0,
            crate::work_context::PaneWorkContext {
                repo: Some("Matthias-Scale/Herdr".into()),
                work_title: Some("Sidebar fixes".into()),
                ..Default::default()
            },
            Default::default(),
        );
        app.set_sidebar_group_mode(SidebarGroupMode::Repo);
        app.reconcile_sidebar_presentation();

        let rows = sidebar_rows(&app);
        assert!(rows.iter().any(|row| matches!(
            row,
            SidebarRow::Workspace { title, .. } if title == "Matthias-Scale/Herdr"
        )));

        let area = Rect::new(0, 0, 18, 12);
        let mut terminal = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
        terminal
            .draw(|frame| render_sidebar(&app, &TerminalRuntimeRegistry::new(), frame, area))
            .unwrap();
        let header = compute_workspace_card_areas(&app, area)
            .into_iter()
            .next()
            .expect("repo header");
        let rendered = row_text(
            terminal.backend().buffer(),
            header.rect.y,
            header.rect.width,
        );
        // The trailing sort control costs the title its cells, so at minimum
        // width the elision starts one column earlier.
        assert!(rendered.starts_with("▾ "), "{rendered:?}");
        assert!(rendered.contains("Matthia"), "{rendered:?}");
        assert!(rendered.contains('…'), "{rendered:?}");
        assert!(rendered.contains(SIDEBAR_SORT_GLYPH), "{rendered:?}");
        assert!(display_width(&rendered) <= usize::from(header.rect.width));
    }

    #[test]
    fn repo_group_state_summary_only_renders_when_collapsed() {
        let mut app = app_with_agents(&["one", "two"]);
        let repo = "owner/a-very-long-repository-name";
        for (ws_idx, state) in [AgentState::Working, AgentState::Blocked]
            .into_iter()
            .enumerate()
        {
            replace_tab_context(
                &mut app,
                ws_idx,
                0,
                crate::work_context::PaneWorkContext {
                    repo: Some(repo.into()),
                    branch: Some("main".into()),
                    ..Default::default()
                },
                Default::default(),
            );
            let pane = app.workspaces[ws_idx].tabs[0].root_pane;
            let terminal_id = app.workspaces[ws_idx].tabs[0].panes[&pane]
                .attached_terminal_id
                .clone();
            app.terminals
                .get_mut(&terminal_id)
                .expect("repo fixture terminal")
                .set_raw_agent_state_for_test(state);
        }
        app.set_sidebar_group_mode(SidebarGroupMode::Repo);
        app.reconcile_sidebar_presentation();
        app.sidebar_presentation
            .expanded_workspace_ids
            .insert(app.workspaces[0].id.clone());

        let group_key = sidebar_rows(&app)
            .into_iter()
            .find_map(|row| match row {
                SidebarRow::Workspace {
                    title,
                    sort_key: Some(sort_key),
                    ..
                } if title == repo => Some(sort_key),
                _ => None,
            })
            .expect("repo group key");
        let collapse_key = format!(
            "{}:{group_key}",
            app.sidebar_group_mode.collapse_namespace()
        );
        let area = Rect::new(0, 0, 40, 20);
        let render_header = |app: &AppState| {
            let mut terminal = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
            terminal
                .draw(|frame| render_sidebar(app, &TerminalRuntimeRegistry::new(), frame, area))
                .unwrap();
            let header = compute_workspace_card_areas(app, area)
                .into_iter()
                .find(|card| card.repo_header)
                .expect("repo header");
            row_text(
                terminal.backend().buffer(),
                header.rect.y,
                header.rect.width,
            )
        };

        app.collapsed_sidebar_groups.insert(collapse_key.clone());
        let collapsed = render_header(&app);
        assert!(collapsed.contains("●1"), "{collapsed:?}");
        assert!(collapsed.contains("○1"), "{collapsed:?}");
        assert!(collapsed.contains('…'), "{collapsed:?}");

        app.collapsed_sidebar_groups.remove(&collapse_key);
        let expanded = render_header(&app);
        assert!(!expanded.contains("●1"), "{expanded:?}");
        assert!(!expanded.contains("○1"), "{expanded:?}");
        assert!(expanded.contains(repo), "{expanded:?}");
        assert!(!expanded.contains('…'), "{expanded:?}");
    }

    #[test]
    fn nested_rows_keep_title_and_machine_at_minimum_width_and_indent_when_space_allows() {
        let mut app = AppState::test_new();
        app.agent_host_name = "ub1".into();
        app.nerd_font = false;
        app.workspaces = vec![Workspace::test_new("repo")];
        app.ensure_test_terminals();
        let pane_id = app.workspaces[0].tabs[0].root_pane;
        let terminal_id = app.workspaces[0].tabs[0].panes[&pane_id]
            .attached_terminal_id
            .clone();
        app.terminals.get_mut(&terminal_id).unwrap().detected_agent = Some(Agent::Codex);
        replace_tab_context(
            &mut app,
            0,
            0,
            crate::work_context::PaneWorkContext {
                pr_urls: vec!["https://github.com/herdrdev/herdr/pull/42".into()],
                work_title: Some("Fix nested row hierarchy".into()),
                ..Default::default()
            },
            Default::default(),
        );
        app.set_sidebar_group_mode(SidebarGroupMode::RepoPr);

        for width in [18, 30] {
            let area = Rect::new(0, 0, width, 12);
            let mut terminal = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
            terminal
                .draw(|frame| render_sidebar(&app, &TerminalRuntimeRegistry::new(), frame, area))
                .unwrap();
            let header = compute_sidebar_nested_header_areas(&app, area)
                .into_iter()
                .find(|header| !header.dim)
                .expect("parent header");
            let child = compute_tab_card_areas(&app, area)
                .into_iter()
                .next()
                .expect("child row");
            let first_non_space = |y, row_width| {
                row_text(terminal.backend().buffer(), y, row_width)
                    .chars()
                    .position(|character| !character.is_whitespace())
                    .expect("visible row content")
            };

            let child_text = row_text(terminal.backend().buffer(), child.rect.y, child.rect.width);
            if width == 18 {
                assert!(child_text.contains('●'), "{child_text:?}");
                let title = child_text
                    .split_once('●')
                    .and_then(|(_, rest)| rest.split_once("cx"))
                    .map(|(title, _)| title.trim())
                    .expect("title before Codex provider");
                assert!(display_width(title) >= 3, "{child_text:?}");
                assert!(child_text.contains('1'), "{child_text:?}");
            } else {
                assert!(
                    first_non_space(header.rect.y, header.rect.width)
                        < first_non_space(child.rect.y, child.rect.width),
                    "parent must start left of child at width {width}"
                );
            }
        }
    }

    #[test]
    fn sidebar_grouping_modes_render_expected_header_tree() {
        let mut app = sidebar_grouping_fixture();
        let tree = |mode| workspace_entry_tree(workspace_list_entries_for_mode(&app, false, mode));
        assert_eq!(tree(SidebarGroupMode::Repo), ["repo:0:false"]);
        assert_eq!(
            tree(SidebarGroupMode::RepoPr),
            [
                "repo:0:false",
                "#159 · pricing",
                "#160 · session fallback",
                unlinked_bucket_title().as_str(),
            ]
        );
        assert_eq!(
            tree(SidebarGroupMode::RepoWorktree),
            [
                "repo:0:false",
                "⎇ feature/pricing",
                "⎇ review/pricing",
                "⎇ session/branch",
                unlinked_bucket_title().as_str(),
            ]
        );
        // Work items are the top level in these modes; this fixture binds none,
        // so every pane lands in the unlinked bucket and no repo header shows.
        assert_eq!(tree(SidebarGroupMode::LinearTeam), ["unlinked"]);
        assert_eq!(tree(SidebarGroupMode::Missive), [unlinked_bucket_title()]);

        let mut tab_sets = Vec::new();
        for mode in SidebarGroupMode::ALL {
            app.set_sidebar_group_mode(mode);
            let rows = sidebar_rows(&app);
            let mut tabs = rows
                .iter()
                .filter_map(|row| match row {
                    SidebarRow::Tab { entry, .. } => entry
                        .local_target()
                        .map(|target| (target.ws_idx, target.tab_idx)),
                    _ => None,
                })
                .collect::<Vec<_>>();
            tabs.sort_unstable();
            tab_sets.push(tabs);
            let nested = rows
                .iter()
                .filter_map(|row| match row {
                    SidebarRow::NestedHeader { title, .. } => Some(title.as_str()),
                    _ => None,
                })
                .collect::<Vec<_>>();
            match mode {
                SidebarGroupMode::Repo => assert_eq!(nested, [unlinked_bucket_title()]),
                SidebarGroupMode::Spaces => assert!(nested.is_empty()),
                SidebarGroupMode::RepoPr => {
                    assert_eq!(
                        nested,
                        [
                            "#159 · pricing",
                            "#160 · session fallback",
                            unlinked_bucket_title().as_str(),
                        ]
                    )
                }
                SidebarGroupMode::RepoWorktree => assert_eq!(
                    nested,
                    [
                        "⎇ feature/pricing",
                        "⎇ review/pricing",
                        "⎇ session/branch",
                        unlinked_bucket_title().as_str(),
                    ]
                ),
                SidebarGroupMode::LinearTeam => assert_eq!(nested, ["unlinked".to_string()]),
                SidebarGroupMode::Missive => assert_eq!(nested, [unlinked_bucket_title()]),
            }
        }
        assert!(tab_sets.windows(2).all(|pair| pair[0] == pair[1]));
    }

    #[test]
    fn sidebar_group_collapse_survives_mode_switch() {
        let mut app = sidebar_grouping_fixture();
        app.set_sidebar_group_mode(SidebarGroupMode::RepoPr);
        let pr_key = "0:https://github.com/scalable-so/herdr/pull/159";
        app.toggle_sidebar_group(pr_key);
        assert!(section_is_collapsed(&app, pr_key));

        app.set_sidebar_group_mode(SidebarGroupMode::RepoWorktree);
        let branch_key = "0:feature/pricing";
        assert!(!section_is_collapsed(&app, branch_key));
        app.toggle_sidebar_group(branch_key);
        assert!(section_is_collapsed(&app, branch_key));

        app.set_sidebar_group_mode(SidebarGroupMode::RepoPr);
        assert!(section_is_collapsed(&app, pr_key));
        assert!(app
            .collapsed_sidebar_groups
            .contains(&format!("repo_pr:{pr_key}")));
        assert!(app
            .collapsed_sidebar_groups
            .contains(&format!("repo_worktree:{branch_key}")));
        assert!(!app
            .collapsed_sidebar_groups
            .iter()
            .any(|key| key.contains("Recently done")));
    }

